"CREATE TABLE IF NOT EXISTS itinerary_days(id INT AUTO_INCREMENT PRIMARY KEY,package_id INT NOT NULL,day_number INT NOT NULL,title VARCHAR(220) NOT NULL,body MEDIUMTEXT NOT NULL,accommodation VARCHAR(220),meals VARCHAR(220),altitude VARCHAR(120),drive_time VARCHAR(120),image VARCHAR(255),UNIQUE KEY uniq_day(package_id,day_number),CONSTRAINT fk_itin_pkg FOREIGN KEY(package_id) REFERENCES packages(id) ON DELETE CASCADE)",
"CREATE TABLE IF NOT EXISTS pages(id INT AUTO_INCREMENT PRIMARY KEY,slug VARCHAR(190) UNIQUE NOT NULL,title VARCHAR(190) NOT NULL,body MEDIUMTEXT,status ENUM('draft','published') DEFAULT 'draft',featured_image VARCHAR(255),meta_title VARCHAR(190),meta_description VARCHAR(255),updated_at DATETIME NOT NULL)",
"CREATE TABLE IF NOT EXISTS destinations(id INT AUTO_INCREMENT PRIMARY KEY,slug VARCHAR(190) UNIQUE NOT NULL,name VARCHAR(190) NOT NULL,summary TEXT,body MEDIUMTEXT,featured_image VARCHAR(255),status ENUM('draft','published') DEFAULT 'draft',meta_title VARCHAR(190),meta_description VARCHAR(255),updated_at DATETIME NOT NULL)",
"CREATE TABLE IF NOT EXISTS articles(id INT AUTO_INCREMENT PRIMARY KEY,slug VARCHAR(190) UNIQUE NOT NULL,title VARCHAR(220) NOT NULL,excerpt TEXT,body MEDIUMTEXT,featured_image VARCHAR(255),status ENUM('draft','published') DEFAULT 'draft',published_at DATETIME NULL,meta_title VARCHAR(190),meta_description VARCHAR(255),updated_at DATETIME NOT NULL)",
