];foreach($schema as $sql){$pdo->exec($sql);}if($_SERVER['REQUEST_METHOD']==='POST'){$email=trim($_POST['email']??'');$pass=$_POST['password']??'';if(filter_var($email,FILTER_VALIDATE_EMAIL)&&strlen($pass)>=10){$st=$pdo->prepare('INSERT INTO admins(email,password_hash,role,created_at) VALUES(?,?,?,NOW()) ON DUPLICATE KEY UPDATE email=email');$st->execute([$email,password_hash($pass,PASSWORD_DEFAULT),'admin']);$msg='Database ready and admin created. Delete or rename this setup file now.';}else{$msg='Use a valid email and a password of at least 10 characters.';}}else{$msg='Database tables are ready. Create the first admin below.';}}catch(Throwable $e){$msg='Database setup failed. Check config.php, database existence, and database privileges.';}
